"""Test from discussion 14184 - arbitrary types with default values"""
from typing import Union, Optional
from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, ConfigDict


class CustomClass:
    def __init__(self, value: str = "default"):
        self.value = value


class Model(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    custom: Union[CustomClass, str] = "default"


app = FastAPI()


@app.post("/")
def foo(req: Model):
    if isinstance(req.custom, CustomClass):
        return {"custom": req.custom.value}
    return {"custom": req.custom}


client = TestClient(app)

# Test with no body
response = client.post("/", json={})
print("Response 1:", response.status_code, response.text)

# Test with custom class
response2 = client.post("/", json={"custom": {"value": "test"}})
print("Response 2:", response2.status_code, response2.text)
EOF
python3 /tmp/test_issue7.py"}

